def transform(grid):
    # Identify rows that do not contain any 9s (clean templates)
    clean_templates = [row for row in grid if 9 not in row]

    result = []
    for row in grid:
        # Find a clean template that matches the pattern of the current row
        # A match means the current row's non-9 values align with the clean row's values
        template = None
        for clean_row in clean_templates:
            match = True
            for c in range(len(row)):
                # If the current row has a valid value (not 9), it must match the template
                if row[c] != 9:
                    if row[c] != clean_row[c]:
                        match = False
                        break
            if match:
                template = clean_row
                break

        if template:
            new_row = list(row)
            for c in range(len(new_row)):
                if row[c] == 9:
                    new_row[c] = template[c]
            result.append(new_row)
        else:
            result.append(list(row))

    return result
